<?php
if(!isset($u,$view)||!function_exists('gcard')){http_response_code(404);exit;}
function gr_search(string $view,array $q,string $extra=''):string{return '<form method="get" data-gfilter>'.gh('view',$view).gf('q','Search','search',$q['q'],'maxlength="120"').$extra.'<div class="gd-buttons"><button class="btn" type="submit">Apply</button>'.gl($view,'Reset').'</div></form>';}
function gr_pages(array $rows,array $headers,string $view,array $q):string{
 $p=gw_page($rows,$q['page'],30);$h=gtable($headers,$p['rows']);$h.='<nav class="gd-buttons" aria-label="Result pages"><span>'.$p['total'].' results · Page '.$p['page'].' of '.$p['pages'].'</span>';
 foreach(['Previous'=>-1,'Next'=>1] as $label=>$d)if($p['page']+$d>0&&$p['page']+$d<=$p['pages'])$h.='<a class="btn" href="'.e(gw_link($view,$q,['page'=>$p['page']+$d])).'">'.$label.'</a>';
 return $h.'</nav>';
}
$q=$grQuery;$cs=[0=>'None / unassigned']+array_column(g_counselors(),'full_name','id');
if(in_array($view,['intake','walkin'],true)){
