 $body='<fieldset class="gu-fieldset"><legend>Request details</legend><div class="gd-fields">'.(is_filer($u)?'':gs('user_id','Verified student requester',array_column($students,'full_name','id'),'','required')).gs('category_id','Service',$cats,$q['category']).gf('subject','Subject','text','','required minlength="5" maxlength="150"').ga('details','Request details','','required minlength="10" maxlength="20000"').'</div></fieldset>';
 $body.='<fieldset class="gu-fieldset"><legend>Preferences and routing</legend><div class="gd-fields">'.gs('priority','Guidance priority',gopts(gr_priorities()),'Normal').gs('preferred_counselor','Preferred counselor (not guaranteed)',$cs).gf('preferred_slot','Preferred time (not an appointment)','datetime-local').($head?gs('assigned_to','Assign now (otherwise use service routing)',$cs):'').'</div><p class="gd-note">High is Guidance-only; common screens retain Normal for compatibility. Service routing may assign a counselor; otherwise the Head reviews the request. A preferred time is not a booking.</p></fieldset>';
 $body.='<fieldset class="gu-fieldset"><legend>Attachments</legend>'.gu_attachments().'</fieldset>';
 echo gcard('Guidance intake',str_replace('<form ','<form enctype="multipart/form-data" ',gform('x.intake',$body,'Submit request')));
}elseif($view==='review'){
 if(!$id){$rows=[];foreach($cases as $t){$m=gone('SELECT review_status FROM gd_plus_cases WHERE ticket_id=?',[$t['id']]);$state=$m['review_status']??'pending';if($q['stage']&&$q['stage']!==$state)continue;if($q['q']!==''&&mb_stripos($t['code'].' '.$t['subject'],$q['q'])===false)continue;$rows[]=[gl('review',$t['code'],(int)$t['id']),e($t['subject']),e($state),e($t['priority'])];}echo gcard('Request review',gr_search('review',$q,gs('stage','Review stage',[''=>'All']+gopts(['pending','in_review','accepted','needs_information']),$q['stage'])).gr_pages($rows,['Request','Subject','Review','Priority'],'review',$q));
 }else{$t=gr_enrich(gr_case($u,$id));$m=gone('SELECT * FROM gd_plus_cases WHERE ticket_id=?',[$id])??[];
 echo gcard($t['code'],'<p>'.e($t['subject']).'</p><p>Shared status: '.e($t['status']).' · Guidance priority: '.e($t['priority']).' · Guidance target: '.e($t['sla_hours']).' hours</p><p>Review: '.e($m['review_status']??'pending').'</p><p>Preferred counselor: '.e($cs[$m['preferred_counselor']??0]??'No longer active').' · Preferred time: '.e($m['preferred_slot']??'None').'</p><a class="btn" href="'.e(url('ticket.php?id='.$id)).'">Open shared request and attachments</a>');
 echo '<div class="gd-grid">';
 if($staff)echo gcard('Review and reprioritize',gform('x.case.review',gh('id',$id).gs('review_status','Review stage',gopts(['pending','in_review','accepted','needs_information']),$m['review_status']??'pending').gs('priority','Guidance priority',gopts(gr_priorities()),$t['priority']).ga('reason','Staff review reason (not included in aggregate exports)','','required minlength="5" maxlength="2000"')));
 $states=$staff?['Escalated'=>'Escalate']:[];if($staff||is_filer($u))$states['Cancelled']='Cancel';
 if($states)echo gcard('Reasoned escalation / cancellation',gform('x.case.transition',gh('id',$id).gs('status','Action',$states).ga('reason','Reason','','required minlength="5" maxlength="2000"'),'Record transition'));
 echo '</div>';
 $logs=gall('SELECT l.*,u.full_name FROM gd_plus_case_log l JOIN users u ON u.id=l.actor_id WHERE ticket_id=?'.($staff?'':' AND actor_id=?').' ORDER BY l.id DESC',$staff?[$id]:[$id,$uid]);$rows=[];foreach($logs as $l)$rows[]=[e($l['created_at']),e($l['full_name']),e($l['action']),e($l['reason'])];echo gcard('Authorized review history',gtable(['When','Actor','Action','Reason'],$rows));}
}elseif($view==='cohort'){
 echo gcard('Preview academic audience','<p>Uses only Guidance metadata explicitly verified against a named school source. Invitations do not reserve seats.</p><form method="get" data-gfilter>'.gh('view','cohort').gh('id',$id).gf('program','Program','text',$q['program'],'maxlength="120"').gf('year_level','Year level','text',$q['year_level'],'maxlength="40"').gf('section','Section','text',$q['section'],'maxlength="80"').'<button class="btn" type="submit">Preview matching students</button></form>');
 if($q['program']||$q['year_level']||$q['section']){$audience=gr_cohort($q);$rows=[];foreach($audience as $a)$rows[]=array_map('e',[$a['full_name'],$a['school_id'],$a['program'],$a['year_level'],$a['section']]);$body=gtable(['Student','School ID','Program','Year','Section'],$rows);
 if(count($audience)>0&&count($audience)<=500)$body.=gform('x.cohort.invite',gh('id',$id).gh('program',$q['program']).gh('year_level',$q['year_level']).gh('section',$q['section']).gh('audience_hash',hash('sha256',json_encode(array_column($audience,'id')))).'<p>Confirm this exact audience. Already invited students will be skipped.</p>','Invite this audience');else $body.='<p>Narrow the audience to 1–500 students.</p>';echo gcard('Audience preview',$body);}
}elseif($view==='register'){
 $rows=[];foreach(gall('SELECT * FROM gd_certificates ORDER BY issued_at DESC,id DESC') as $c){if($q['q']!==''&&mb_stripos($c['recipient_name'].' '.$c['event_title'].' '.$c['verify_code'],$q['q'])===false)continue;if($q['from']&&substr($c['issued_at'],0,10)<$q['from'])continue;if($q['to']&&substr($c['issued_at'],0,10)>$q['to'])continue;$rows[]=[e($c['recipient_name']),e($c['event_title']),e($c['issued_at']),e($c['credits']),'<a class="btn" href="'.e(url('guidance/certificate.php?id='.$c['id'])).'">View / print</a>'];}
 echo gcard('Certificate register',gr_search('register',$q,gf('from','Issued from','date',$q['from']).gf('to','Issued to','date',$q['to'])).gr_pages($rows,['Recipient','Activity','Issued','Credits','Certificate'],'register',$q));
 echo gcard('Issue one eligible certificate','<p>Open an activity to issue to an eligible attendee. Completion, certificate setting and registered attendance are checked again on save.</p>'.gl('events','Open activities'));
}elseif($view==='notifications'){
 $rows=[];foreach(gall('SELECT n.*,l.view_name,l.record_id FROM notifications n LEFT JOIN gd_plus_notices l ON l.notification_id=n.id WHERE n.user_id=? ORDER BY n.id DESC',[$uid]) as $n){if($q['stage']==='unread'&&$n['read_at'])continue;if($q['q']!==''&&mb_stripos($n['title'].' '.$n['body'],$q['q'])===false)continue;
 $link='';if($n['ticket_id']){$t=gone('SELECT * FROM tickets WHERE id=?',[$n['ticket_id']]);if($t&&g_case($u,$t))$link='<a class="btn" href="'.e(url('ticket.php?id='.$n['ticket_id'])).'">Open request</a>';}
 elseif(in_array($n['view_name'],['event','appointments','history','settings','requests'],true))$link=gl($n['view_name'],'Open workspace',(int)$n['record_id']);
 elseif(str_contains(mb_strtolower($n['title']),'appointment'))$link=gl('appointments','Appointments');elseif(str_contains(mb_strtolower($n['title']),'invitation'))$link=gl('events','Activities');
 $rows[]=[e($n['created_at']),e($n['title']),e($n['body']),$link.($n['read_at']?'Read':gform('x.notice.read',gh('id',$n['id']),'Mark read'))];}
 echo gcard('Your notifications',gform('x.notices.readall','<p>Mark your own campus notifications as read. This does not dismiss other users’ notices.</p>','Mark all my notices read').gr_search('notifications',$q,gs('stage','State',[''=>'All','unread'=>'Unread'],$q['stage'])).gr_pages($rows,['When','Title','Message','Action'],'notifications',$q));
}elseif($view==='knowledge'){
 echo gcard('Find resources',gr_search('knowledge',$q));
 if($staff)echo gcard('Publish a resource',gdetails('New article',gform('article.save',gf('title','Title','text','','required minlength="3" maxlength="160"').ga('body','Body','','required minlength="10" maxlength="30000"').gc('published','Published'))));
 $articles=gall('SELECT * FROM gd_articles'.($staff?'':' WHERE published=1').' ORDER BY updated_at DESC,id DESC');$articles=array_values(array_filter($articles,fn($a)=>$q['q']===''||mb_stripos($a['title'].' '.$a['body'],$q['q'])!==false));$pg=gw_page($articles,$q['page'],20);
 foreach($pg['rows'] as $a){$b='<div class="gd-pre">'.e($a['body']).'</div>';if($staff)$b.=gdetails('Edit resource',gform('article.save',gh('id',$a['id']).gf('title','Title','text',$a['title'],'required maxlength="160"').ga('body','Body',$a['body'],'required maxlength="30000"').gc('published','Published',(bool)$a['published'])));echo gcard($a['title'],$b);}
 echo '<p>'.$pg['total'].' resources · Page '.$pg['page'].' of '.$pg['pages'].'</p>';foreach(['Previous'=>-1,'Next'=>1] as $label=>$d)if($pg['page']+$d>0&&$pg['page']+$d<=$pg['pages'])echo '<a class="btn" href="'.e(gw_link('knowledge',$q,['page'=>$pg['page']+$d])).'">'.$label.'</a>';
}elseif($view==='help'){
 echo gcard('Guidance help','<p>For immediate danger, contact local emergency services or a trusted person nearby. This portal is not monitored as an emergency service. No 24-hour response or automatic emergency paging is promised.</p><div class="gd-buttons">'.gl('intake','Send a Guidance request').gl('appointments','Appointments').gl('knowledge','Find resources').'</div><p>To ask for help, use a real Guidance request above. There is no simulated “message sent” button.</p>');
 $rows=[];foreach(gall("SELECT c.id,c.name,s.description,p.name parent,s.low_hours,s.normal_hours,s.high_hours,s.urgent_hours FROM categories c LEFT JOIN gd_plus_services s ON s.category_id=c.id LEFT JOIN categories p ON p.id=s.parent_id WHERE c.office_code='guide' AND c.is_hidden=0 ORDER BY c.sort_order,c.name") as $c){if($q['q']!==''&&mb_stripos($c['name'].' '.$c['description'],$q['q'])===false)continue;$rows[]=[e($c['name']),e($c['parent']??'—'),e($c['description']??'Contact Guidance for service details.'),'<a class="btn" href="'.e(gw_link('intake',['category'=>$c['id']])).'">Request service</a>'];}echo gcard('Service catalogue',gr_search('help',$q).gtable(['Service','Parent','Description','Request'],$rows));
}elseif($view==='audit'){
 $rows=gr_audit_rows($q);$data=[];foreach($rows as $r)$data[]=array_map('e',array_values($r));
 echo gcard('Guidance audit',gr_search('audit',$q,gf('from','From','date',$q['from']).gf('to','To','date',$q['to']).gf('actor','Exact actor username','text',$q['actor'],'maxlength="120"').gf('action','Exact action','text',$q['action'],'maxlength="80"')).'<p>Operational audit export omits descriptions, IP addresses and clinical content, and withholds requester identities. Search matches action/actor, not clinical narratives.</p><a class="btn" href="'.e(url('guidance/restoration-export.php?'.http_build_query($q))).'">Download filtered audit CSV</a>'.gr_pages($data,['When','Actor','Action'],'audit',$q));
 }elseif($view==='privacy'){
 $requests=gall('SELECT p.*,u.full_name,x.stage FROM gd_privacy p JOIN users u ON u.id=p.user_id LEFT JOIN gd_plus_privacy x ON x.privacy_id=p.id ORDER BY p.updated_at DESC');
 foreach($requests as $r){
  $body='<div class="gu-record-meta">'.gtag($r['stage']??$r['status']).'<span>Request #'.(int)$r['id'].' · Updated '.e(fmt_dt($r['updated_at'])).'</span></div><dl><dt>Request</dt><dd class="gd-pre">'.e($r['reason']).'</dd><dt>Latest response</dt><dd class="gd-pre">'.e($r['response']??'Awaiting review.').'</dd></dl>';
  $body.=gdetails('Update review stage',gform('x.privacy',gh('id',$r['id']).gs('stage','Review stage',gopts(['in_review','awaiting_requester','completed','declined']),$r['stage']??'in_review').ga('response','Response shared with requester',$r['response']??'','required minlength="10" maxlength="4000"'),'Record stage and response'));
  echo gcard('Privacy review · '.$r['full_name'],$body.gu_privacy_history((int)$r['id']));
 }
 if(!$requests)echo gcard('Privacy reviews',gempty('No privacy requests awaiting review.'));
}elseif($view==='operations'){
 $rows=[['Restoration extension','Enabled'],['Last Guidance scheduled job',gone("SELECT setting_value FROM gd_settings WHERE setting_key='last_job'")['setting_value']??'Not recorded'],['Last verified scheduled backup',gone("SELECT setting_value FROM gd_settings WHERE setting_key='last_plus_backup'")['setting_value']??'Not recorded'],['Backup key in this PHP process',getenv('LCCT_GUIDANCE_BACKUP_KEY')?'Present; validated during backup, value hidden':'Not present; the scheduled task may use a separate private environment'],['Shared full-system restore','Owner-coordinated; not exposed here'],['Clinical email','Suppressed by design; in-app notices are not email delivery']];
 echo gcard('Guidance operations',gtable(['Check','State'],array_map(fn($r)=>array_map('e',$r),$rows)).'<p>No passwords, encryption keys or filesystem paths are displayed. A recorded backup is not proof of full-system recoverability.</p><p>Use the packaged <code>guidance/schedule-restoration.ps1</code> for a Guidance-only daily job and verified encrypted subset backup. Scheduling is opt-in; nothing is installed by visiting this page.</p><p>Full database restore, remote deployment, historical data import, and common student password recovery require the shared application owner. There is no destructive web restore button.</p>');
